# --- Vinyl effect: record photo (embedded below), only the label + album art spins ---
VINYL_RPM = 33.33          # label rotation speed
VINYL_SRC = 744            # source image is a 744x744 square around the disc
VINYL_CLIP_R = 369.0       # disc radius in source px (everything outside is cut away)
VINYL_LABEL_R = 141.0      # white label radius in source px (album art goes here)
_vinyl_disc_pb = None


def vinyl_disc_pixbuf():
    """Decode the embedded record photo once; returns a Pixbuf or None."""
    global _vinyl_disc_pb
    if _vinyl_disc_pb is None:
        try:
            loader = GdkPixbuf.PixbufLoader.new_with_type("jpeg")
            loader.write(base64.b64decode(VINYL_DISC_JPEG_B64))
            loader.close()
            _vinyl_disc_pb = loader.get_pixbuf() or False
        except Exception as e:
            print(f"Vinyl image decode error: {e}")
            _vinyl_disc_pb = False
    return _vinyl_disc_pb or None


