def fmt_time(seconds):
    s = max(int(seconds), 0)
    h, rem = divmod(s, 3600)
    m, s = divmod(rem, 60)
    return f"{h}:{m:02d}:{s:02d}" if h else f"{m}:{s:02d}"


def to_int(v, default=0):
    try:
        return int(float(v))
    except Exception:
        return default


def decode_text(raw):
    """Same decoding the poller uses: url-unquote, then hex-decode if it looks like hex."""
    t = urllib.parse.unquote(str(raw or ""))
    if t and all(c in "0123456789ABCDEFabcdef" for c in t) and len(t) % 2 == 0:
        try:
            t = bytes.fromhex(t).decode('utf-8', errors='ignore')
        except Exception:
            pass
    return t


def norm(s):
    return (s or "").strip().lower()


def load_index_base():
    try:
        with open(INDEX_FILE) as f:
            return int(f.read().strip())
    except Exception:
        return INDEX_BASE


def save_index_base(v):
    try:
        with open(INDEX_FILE, "w") as f:
            f.write(str(v))
    except Exception:
        pass


# --- audio format (codec / sample rate / bit depth / bitrate) ---
CODEC_MAP = {
    "flac": "FLAC", "mpeg": "MP3", "mp3": "MP3", "mpeg3": "MP3",
    "mp4": "AAC", "aac": "AAC", "m4a": "AAC", "mp4a-latm": "AAC", "aacp": "AAC",
    "alac": "ALAC", "wav": "WAV", "wave": "WAV", "l16": "PCM", "pcm": "PCM",
    "ogg": "OGG", "vorbis": "Vorbis", "opus": "Opus", "ape": "APE",
    "wma": "WMA", "ms-wma": "WMA", "dsd": "DSD", "dsf": "DSD", "dff": "DSD",
}
_EMPTY = ("", "0", "unknown", "null", "none", "n/a")


def pick(d, names):
    low = {str(k).lower(): v for k, v in d.items()} if isinstance(d, dict) else {}
    for n in names:
        v = low.get(n)
        if v is not None and str(v).strip().lower() not in _EMPTY:
            return str(v).strip()
    return None


def nice_codec(c):
    low = str(c).strip().lower()
    if low.startswith("audio/"):
        low = low[6:]
    if low.startswith("x-"):
        low = low[2:]
    return CODEC_MAP.get(low, str(c).strip().upper() if len(str(c)) <= 5 else str(c).strip())


def extract_audio_info(d):
    info = {}
    for key, names in (
        ("codec", ["codec", "audiocodec", "audioformat", "format_s", "encoding", "audiotype"]),
        ("rate", ["samplerate", "sample_rate", "rate_hz", "samplingrate"]),
        ("depth", ["bitdepth", "bit_depth", "bitspersample"]),
        ("bitrate", ["bitrate", "bit_rate"]),
    ):
        v = pick(d, names)
        if v:
            info[key] = v
    return info


def parse_upnp_audio_info(raw):
    """Pull codec/rate/depth/bitrate out of the AVTransport track metadata (DIDL-Lite)."""
    txt = raw
    for _ in range(3):
        txt = html.unescape(txt)
    info = {}
    for key, tags in (("codec", ["song:format_s"]), ("rate", ["song:rate_hz"]),
                      ("depth", ["song:bitDepth", "song:bit_depth"]), ("bitrate", ["song:bitrate"])):
        for t in tags:
            v = _val(txt, t)
            if v and v.strip().lower() not in _EMPTY:
                info[key] = v.strip()
                break
    m = re.search(r'sampleFrequency="(\d+)"', txt)
    if m and "rate" not in info:
        info["rate"] = m.group(1)
    m = re.search(r'bitsPerSample="(\d+)"', txt)
    if m and "depth" not in info:
        info["depth"] = m.group(1)
    if "codec" not in info:
        m = re.search(r'protocolInfo="[^"]*?:(audio/[A-Za-z0-9.+\-]+)', txt)
        if m and m.group(1).lower() not in ("audio/*",):
            info["codec"] = m.group(1)
    if "codec" not in info:
        m = re.search(r"\.(flac|mp3|m4a|aac|wav|ogg|opus|alac|ape|wma|dsf|dff)(?:\?|<|\"|$)", txt, re.I)
        if m:
            info["codec"] = m.group(1)
    if "bitrate" not in info:
        m = re.search(r'<res[^>]*?\sbitrate="(\d+)"', txt)   # DLNA bitrate = bytes/s
        if m and int(m.group(1)) > 0:
            info["bitrate"] = str(int(m.group(1)) * 8 // 1000)
    return info


def format_audio_info(info):
    parts = []
    if info.get("codec"):
        parts.append(nice_codec(info["codec"]))
    try:
        hz = float(info["rate"])
        if hz < 1000:
            hz *= 1000
        if hz > 0:
            parts.append(f"{hz / 1000:g} kHz")
    except Exception:
        pass
    try:
        d = int(float(info["depth"]))
        if d > 0:
            parts.append(f"{d}-bit")
    except Exception:
        pass
    try:
        b = float(info["bitrate"])
        if b > 20000:
            b /= 1000
        if b > 0:
            parts.append(f"{int(round(b))} kbps")
    except Exception:
        pass
    return "  \u00b7  ".join(parts)
# --- end audio format ---


# --- queue parsing ---
def _val(text, tag):
    m = re.search(rf"<{re.escape(tag)}>(.*?)</{re.escape(tag)}>", text, re.S)
    return html.unescape(m.group(1)).strip() if m else ""


def parse_queue(raw):
    """Parse a BrowseQueue SOAP response -> (list_name, source, [(title, artist), ...]) or None.

    The device escapes the XML several times (SOAP -> QueueContext -> Metadata -> text),
    so each layer gets one html.unescape().
    """
    m = re.search(r"<QueueContext>(.*?)</QueueContext>", raw, re.S)
    if not m:
        return None
    ctx = html.unescape(m.group(1))
    tracks = []
    for n, blk in enumerate(re.findall(r"<Track\d+>(.*?)</Track\d+>", ctx, re.S), 1):
        md = re.search(r"<Metadata>(.*?)</Metadata>", blk, re.S)
        didl = html.unescape(md.group(1)) if md else ""
        title = _val(didl, "dc:title") or f"Track {n}"
        artist = _val(didl, "upnp:artist")
        tracks.append((title, artist))
    return _val(ctx, "ListName"), _val(ctx, "SourceName"), tracks
# --- end queue parsing ---


class TrayItem:
    """Minimal StatusNotifierItem: left click -> on_activate, right click -> on_context."""
    def __init__(self, icon_name, icon_dir, on_activate, on_context):
        self.icon_name = icon_name
        self.icon_dir = icon_dir
        self.on_activate = on_activate
        self.on_context = on_context
        self.bus_name = f"org.kde.StatusNotifierItem-{os.getpid()}-1"

        self.conn = Gio.bus_get_sync(Gio.BusType.SESSION, None)
        info = Gio.DBusNodeInfo.new_for_xml(SNI_XML)
        self.conn.register_object(
            "/StatusNotifierItem", info.interfaces[0],
            self._on_call, self._on_get_property, None
        )
        Gio.bus_own_name_on_connection(
            self.conn, self.bus_name, Gio.BusNameOwnerFlags.NONE,
            lambda conn, name: self._register(), None
        )
        # Re-register if plasmashell restarts
        Gio.bus_watch_name_on_connection(
            self.conn, "org.kde.StatusNotifierWatcher", Gio.BusNameWatcherFlags.NONE,
            lambda conn, name, owner: self._register(), None
        )

    def _register(self):
        self.conn.call(
            "org.kde.StatusNotifierWatcher", "/StatusNotifierWatcher",
            "org.kde.StatusNotifierWatcher", "RegisterStatusNotifierItem",
            GLib.Variant("(s)", (self.bus_name,)), None,
            Gio.DBusCallFlags.NONE, -1, None, None, None
        )

    def _on_call(self, conn, sender, path, iface, method, params, invocation):
        if method == "Activate":
            GLib.idle_add(self.on_activate)
        elif method == "ContextMenu":
            x, y = params.unpack()
            GLib.idle_add(self.on_context, x, y)
        invocation.return_value(None)

    def _on_get_property(self, conn, sender, path, iface, prop):
        values = {
            "Category": GLib.Variant("s", "ApplicationStatus"),
            "Id": GLib.Variant("s", "wiim-tray-controller"),
            "Title": GLib.Variant("s", "WiiM Controller"),
            "Status": GLib.Variant("s", "Active"),
            "WindowId": GLib.Variant("u", 0),
            "IconName": GLib.Variant("s", self.icon_name),
            "IconThemePath": GLib.Variant("s", self.icon_dir),
            "ItemIsMenu": GLib.Variant("b", False),  # False => left click calls Activate
        }
        return values.get(prop)


class WiiMControllerApp:
    _vinyl_geo = None          # (x, y, w, h) of the spinning label, used for partial redraws
    _vinyl_cache = None
    _vinyl_broken = False
    _fx_cost = 0.0
    _fx_slow = False
    _fx_phase = 0

    def __init__(self):
        self.wiim_ip = None
        try:
            with open(os.path.join(ICON_DIR, "wiim_tray_device_ip.txt"), "r") as ip_file:
                candidate_ip = ip_file.read().strip()
                if candidate_ip.count(".") == 3:
                    self.wiim_ip = candidate_ip
        except OSError:
            pass
        self.is_playing = False
        self.volume = 50
        self.muted = False
        self.album_art_url = ""
        self.is_scanning = False
        self.fail_count = 0
        self.raw_pixbuf = None
        self.updating_slider = False
        self.updating_prog = False
        self.seeking = False
        self.pos_ms = 0
        self.tot_ms = 0
        self.pos_time = time.monotonic()
        self._range_tot = -1
        self.minimized = False
        self.pinned = False
        self.saved_geom = None  # (x, y, w, h) remembered between shows
        self.current_title = ""
        self.queue_dirty = True
        self.queue_fetching = False
        self.edge_cursor = None
        self.cur_row_widget = None
        self.pl_open = False
        self.expand_shift = 0
        self.audio_dirty = True
        self.audio_fetching = False
        self.audio_tries = 0
        self.queue_tracks = []
        self.index_base = load_index_base()
        self.connect_stopped = False
        self.source_mode = ""
        self.art_generation = 0
        self.poll_fetching = False
        self.queue_retry_at = 0.0
        self.queue_failures = 0
        self.queue_error = ""
        self.volume_timer = None
        self.commands = queue.Queue(maxsize=32)
        threading.Thread(target=self.command_worker, daemon=True).start()

        provider = Gtk.CssProvider()
        provider.load_from_data(CSS_STYLE)
        Gtk.StyleContext.add_provider_for_screen(
            Gdk.Screen.get_default(),
            provider,
            Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION
        )
        # click on a slider trough jumps straight there (like macOS)
        Gtk.Settings.get_default().set_property("gtk-primary-button-warps-slider", True)

        ensure_icon()

        # Right-click menu (Quit only)
        self.menu = Gtk.Menu()
        item_quit = Gtk.MenuItem(label="Quit WiiM Controller")
        item_quit.connect("activate", self.quit_app)
        self.menu.append(item_quit)
        self.menu.show_all()

        # Tray icon: left click toggles window, right click shows menu
        self.tray = TrayItem(TRAY_ICON_NAME, ICON_DIR, self.toggle_window, self.show_menu)

        # Main window: frameless + transparent so the rounded corners show
        self.window = Gtk.Window(type=Gtk.WindowType.TOPLEVEL)
        screen = self.window.get_screen()
        visual = screen.get_rgba_visual()
        if visual is not None and screen.is_composited():
            self.window.set_visual(visual)
        self.window.get_style_context().add_class("wiim-player")
        self.window.set_app_paintable(True)
        self.window.set_title("WiiM Controller")
        try:
            self.window.set_icon_from_file(TRAY_ICON_PATH)
        except GLib.Error:
            pass
