_WIIM_PRESENT = "#version 150\nuniform sampler2D diamondTex,coverTex;\nuniform vec2 screenSize;\nuniform float panel,diamondSpan,motionTime;\nout vec4 color;\nmat2 rotate2(float a){float c=cos(a),s=sin(a);return mat2(c,s,-s,c);}\nfloat hash2(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nvec2 mirrored(vec2 p){return 1.0-abs(mod(p,2.0)-1.0);}\nvoid main(){\n vec2 area=vec2(screenSize.x,max(1.0,screenSize.y-panel));\n vec2 point=gl_FragCoord.xy-vec2(0,panel);\n if(point.y<0){color=vec4(0,0,0,1);return;}\n vec2 view=(point-area*.5)/min(area.x,area.y);\n float t=motionTime,angle=.055*t+.12*sin(t*.07);\n mat2 rotation=rotate2(angle+.7853981633974483);\n vec2 moving=rotation*view;\n float pitch=160.0/diamondSpan;\n vec2 grid=moving*pitch+80.0;\n // Gentle shear links the scales into a moving, flexible skin.\n grid.x+=.32*sin(grid.y*.10-t*.22);\n vec2 parent=floor(grid*.5);\n float size=hash2(parent+3.7)<.32?2.0:1.0;\n vec2 origin=size>1.5?parent*2.0:floor(grid);\n vec2 centre=origin+size*.5;\n float random=hash2(origin+vec2(17,43));\n vec2 local=(grid-centre)/(size*.5);\n local=rotate2(.13*sin(t*.19+random*6.2831853))*local;\n float radius=.78+.12*random;\n vec2 p=local/radius;\n float shape=pow(abs(p.x),4.0)+pow(abs(p.y),4.0);\n float aa=max(fwidth(shape),.015);\n float mask=1.0-smoothstep(1.0-aa,1.0+aa,shape);\n // Sample the calculated fractal at each moving scale's centre.\n vec2 centreWorld=view+transpose(rotation)*((centre-grid)/pitch);\n vec2 q=vec2(centreWorld.x+centreWorld.y,centreWorld.y-centreWorld.x)*.7071067811865476;\n ivec2 cell=clamp(ivec2(floor((q/diamondSpan+.5)*160.0)),ivec2(0),ivec2(159));\n vec3 pigment=texelFetch(diamondTex,cell,0).rgb;\n float rim=smoothstep(.48,1.0,shape);\n float light=1.02-.16*rim+.10*(p.y-p.x);\n float sheen=.12*exp(-7.0*dot(p-vec2(-.24,.24),p-vec2(-.24,.24)));\n vec3 scaleColor=pigment*light+pigment*sheen;\n // The same rotation drives the liquid beneath the scales.\n float twist=angle+.65*sin(length(view)*2.8-t*.11);\n vec2 liquid=rotate2(twist)*view;\n liquid+=.045*vec2(sin(view.y*5.0-t*.16),cos(view.x*4.0+t*.13));\n liquid+=transpose(rotation)*(local*.009*rim);\n vec2 uv=mirrored(liquid*.72+.5+vec2(.025*sin(t*.09),.025*cos(t*.08)));\n uv.y=1.0-uv.y;\n vec3 background=texture(coverTex,uv).rgb*.72;\n color=vec4(clamp(mix(background,scaleColor,mask),0.0,1.0),1.0);\n}\n"

